from typing import List

def solution(laps: List[List[str]]) -> List[str]:
    best, alive, order = {}, None, []
    for lap in laps:
        for entry in lap:
            name, t = entry.rsplit(maxsplit=1)
            t = int(t)
            if alive is None or name in alive:
                best[name] = min(best.get(name, t), t)
        if alive is None:
            alive = set(best)
        if len(alive) <= 1:
            break
        worst = max(best[d] for d in alive)
        out = sorted(d for d in alive if best[d] == worst)
        order += out
        alive -= set(out)
    order += sorted(alive or [])
    return order
